 static void Pyroblast(){
  var g=Game();int card=Hand(g,"EX1_279");Check(g.Play(0,card,new MatchTarget(1)).Success&&g.Players[1].Health==20&&!g.SpellImpactPending&&!g.AnimationPlaying,"Disabled effects retain instant spell rules");
  DateTime now=new DateTime(2026,10,13,0,0,0,DateTimeKind.Utc);g=Game();g.AnimationNowUtc=()=>now;g.EntranceAnimationsEnabled=true;card=Hand(g,"EX1_279");Check(g.Play(0,card,new MatchTarget(1)).Success&&g.Players[0].Mana==0&&g.Players[0].Hand.Count==0&&g.Players[1].Health==30&&g.SpellImpactPending&&g.AnimationPlaying,"Paid spell waits without early health change");Check(!g.HeroPower(0,new MatchTarget(1)).Success&&g.Players[1].Health==30,"Animation wait blocks follow-up actions");now=now.AddMilliseconds(999);Check(!g.PollSpellImpact()&&!g.VisualEvents.Any(e=>e.Kind=="damage"),"No damage event before collision");now=now.AddMilliseconds(1);Check(g.PollSpellImpact()&&g.Players[1].Health==20&&g.VisualEvents.Count(e=>e.Kind=="pyroblast-impact")==1&&g.VisualEvents.Count(e=>e.Kind=="damage")==1,"Collision resolves actual health and public impact together");Check(!g.PollSpellImpact()&&g.Players[1].Health==20,"Impact cannot resolve twice");Check(g.VisualEvents.First(e=>e.Kind=="pyroblast").Action==g.VisualEvents.First(e=>e.Kind=="damage").Action,"Damage is tied to the original spell timeline");
  g=Game();g.AnimationNowUtc=()=>now;g.EntranceAnimationsEnabled=true;var unit=g.Summon(1,"VAN_CS2_182");g.SetHealth(new MatchTarget(1,unit.Id),3);g.Play(0,Hand(g,"EX1_279"),new MatchTarget(1,unit.Id));Check(g.Players[1].Board.Count==1&&unit.Health==3,"Lethal target remains alive throughout flight");now=now.AddMilliseconds(1000);g.PollSpellImpact();Check(g.Players[1].Board.Count==0&&g.VisualEvents.Last(e=>e.Kind=="death").Overkill==7,"Collision then emits correct death shatter");
  g=Game();g.AnimationNowUtc=()=>now;g.EntranceAnimationsEnabled=true;unit=g.Summon(1,"VAN_EX1_008");g.Play(0,Hand(g,"EX1_279"),new MatchTarget(1,unit.Id));now=now.AddMilliseconds(1000);g.PollSpellImpact();Check(!unit.Shield&&unit.Health==1&&g.VisualEvents.Any(e=>e.Kind=="pyroblast-impact")&&!g.VisualEvents.Any(e=>e.Kind=="damage"),"Shield absorbs damage at impact without fake damage numbers");
  g=Game();g.Active=1;g.Play(1,Hand(g,"EX1_287",1));g.Active=0;g.EntranceAnimationsEnabled=true;g.Play(0,Hand(g,"EX1_279"),new MatchTarget(1));Check(!g.SpellImpactPending&&!g.VisualEvents.Any(e=>e.Kind=="pyroblast")&&g.Players[1].Health==30,"Countered Pyroblast never launches");
  g=Game();g.AnimationNowUtc=()=>now;g.EntranceAnimationsEnabled=true;unit=g.Summon(0,"VAN_NEW1_020");g.Play(0,Hand(g,"EX1_279"),new MatchTarget(1));Check(unit.Health==2,"Spell-resolved trigger waits for effect resolution");now=now.AddMilliseconds(1000);g.PollSpellImpact();Check(unit.Health==1&&g.Players[1].Health==20,"Spell-resolved triggers execute after actual collision");
  g=Game();g.AnimationNowUtc=()=>now;g.EntranceAnimationsEnabled=true;g.Summon(0,"VAN_EX1_559");g.Play(0,Hand(g,"EX1_279"),new MatchTarget(1));Check(g.Players[0].Hand.Count==1&&g.Card(g.Players[0].Hand[0].CardId).BaseId=="CS2_029"&&g.Players[1].Health==30,"Spell-cast triggers keep original cast timing");g.EntranceAnimationsEnabled=false;now=now.AddMilliseconds(1000);Check(g.PollSpellImpact()&&g.Players[1].Health==20,"Turning effects off cannot skip scheduled damage");
  var host=new LanHostGame(catalog,matchRules.TrainingDeck("MAGE"),matchRules.TrainingDeck("WARRIOR"),8,0);g=host.Game;g.MarkMulliganCompleteForTests();g.Players[0].Hand.Clear();g.Players[0].Mana=10;g.AnimationNowUtc=()=>now;host.SetPresentation(0,false);host.SetPresentation(1,true);card=Hand(g,"EX1_279");var result=host.Execute(0,new LanCommand{Kind="play",Source=card,Target=new MatchTarget(1),Session=host.Session,Revision=host.Revision});var view=LanProtocol.ReadView(catalog,host.Snapshot().State);Check(result.Success&&view.AnimationPlaying&&view.Players[1].Health==30,"One enabled peer creates a shared pre-impact wait");int revision=host.Revision;now=now.AddMilliseconds(1000);Check(host.PollTimeout()&&host.LastPollResolvedSpell&&host.Revision==revision+1,"Host advances revision exactly at delayed impact");view=LanProtocol.ReadView(catalog,host.Snapshot().State);Check(view.Players[1].Health==20&&view.VisualEvents.Any(e=>e.Kind=="pyroblast-impact"&&e.TargetSeat==1)&&view.Players[0].Hand.Count==0,"Authoritative hit snapshot preserves privacy and target identity");
  g=Game();g.AnimationNowUtc=()=>now;g.EntranceAnimationsEnabled=true;g.Play(0,Hand(g,"EX1_279"),new MatchTarget(1));now=now.AddMilliseconds(3000);Check(g.AnimationPlaying&&!g.EndTurn().Success&&g.Players[1].Health==30,"Delayed polling cannot unlock actions before pending damage");Check(g.PollSpellImpact()&&g.Players[1].Health==20&&!g.AnimationPlaying,"Overdue impact still resolves once before unlocking");
  long turnTime=0;g=Game();g.ClockNowMs=()=>turnTime;g.AnimationNowUtc=()=>now;g.EntranceAnimationsEnabled=true;g.Summon(0,"VAN_EX1_560");g.Play(0,Hand(g,"EX1_279"),new MatchTarget(1));turnTime=15001;now=now.AddMilliseconds(999);Check(!g.TryEndTimedTurn()&&g.Active==0,"Nozdormu cannot change sides mid-flight");now=now.AddMilliseconds(1);g.PollSpellImpact();now=now.AddMilliseconds(601);Check(g.Players[1].Health==20&&g.TryEndTimedTurn()&&g.Active==1,"Expired turn advances after hit and animation gate");
